public static ReasonTable metFindReasonCodeForVarianceType(METVarianceType _varianceType, boolean _forUpdate = false)
{
    ReasonTable reason;
    NoYes createClaim = (_varianceType == METVarianceType::PriceVarianceOver
                      || _varianceType == METVarianceType::QuantityVarianceOver
                      || _varianceType == METVarianceType::QuantityVarianceNoDelivery) ? NoYes::Yes : NoYes::No;

    if (createClaim == NoYes::Yes)
    {
        select firstonly reason
            where reason.METVarianceType == _varianceType
            && reason.METClaim == createClaim
            && reason.METInvoiceMatch == NoYes::Yes;
    }
    else
    {
        select firstonly reason
            where reason.METVarianceType == _varianceType
            && reason.METInvoiceMatch == NoYes::Yes;
    }

    reason.selectForUpdate(_forUpdate);

    return reason;
}
